TEXT['app.py'] = '"""\nSweet Bean Canteen — demo site\nRun:  pip install flask\n      python app.py\nThen open http://127.0.0.1:5000\n"""\nimport calendar\nimport os\nfrom datetime import date, datetime\nfrom functools import wraps\n\nfrom flask import (Flask, render_template, request, redirect, url_for,\n                   session, flash, abort)\n\nimport models\nfrom emailer import notify_owner\n\napp = Flask(__name__)\napp.secret_key = os.environ.get("SECRET_KEY", "dev-secret-change-me")\n\n# Owner password for the admin page (set ADMIN_PASSWORD on Render).\nADMIN_PASSWORD = os.environ.get("ADMIN_PASSWORD", "sweetbean")\n\nmodels.init_db()\n\n\ndef login_required(f):\n    @wraps(f)\n    def wrapper(*args, **kwargs):\n        if not session.get("admin"):\n            return redirect(url_for("admin_login", next=request.path))\n        return f(*args, **kwargs)\n    return wrapper\n\n# ---------------------------------------------------------------\n# BUSINESS INFO (real — pulled from their public listings)\n# ---------------------------------------------------------------\nBUSINESS = {\n    "name": "Sweet Bean Canteen",\n    "tagline": "Specialty coffee, brunch & a trailer that travels — right off Main Street.",\n    "address": "215 W Main St, Chouteau, OK 74337",\n    "phone": "(918) 803-3043",\n    "phone_href": "tel:+19188033043",\n    "hours": [\n        ("Monday",    "6:30 AM – 2:00 PM"),\n        ("Tuesday",   "6:30 AM – 2:00 PM"),\n        ("Wednesday", "6:30 AM – 6:00 PM"),\n        ("Thursday",  "6:30 AM – 6:00 PM"),\n        ("Friday",    "6:30 AM – 6:00 PM"),\n        ("Saturday",  "8:00 AM – 2:00 PM"),\n        ("Sunday",    "Closed"),\n    ],\n    "facebook": "https://www.facebook.com/profile.php?id=100087205220380",\n    "doordash": "https://www.doordash.com/store/sweet-bean-canteen-chouteau-34474227/",\n    # Keyless Google Maps embed (no API key needed for this iframe style)\n    "map_embed": "https://maps.google.com/maps?q=215+W+Main+St,+Chouteau,+OK+74337&z=15&output=embed",\n}\n\n# ---------------------------------------------------------------\n# MENU HIGHLIGHTS (demo — confirm names/prices with the client)\n# ---------------------------------------------------------------\nMENU = [\n    {\n        "name": "Grandma\'s Cookies Latte",\n        "desc": "Warm cookie sweetness. Espresso backbone. Tastes like a hug.",\n        "tag": "Fan favorite",\n    },\n    {\n        "name": "Peaches n Cream",\n        "desc": "Bright peach, silky cream. Summer in a 24oz cup.",\n        "tag": "Seasonal",\n    },\n    {\n        "name": "Fresh Fruit Teas",\n        "desc": "Iced tea with real fruit. No syrup-lab shortcuts.",\n        "tag": "Refresher",\n    },\n    {\n        "name": "Croissant Sandwiches",\n        "desc": "Flaky, buttery, built to order. Wraps and platters too.",\n        "tag": "Brunch",\n    },\n]\n\n# ---------------------------------------------------------------\n# REVIEWS (demo placeholders written from real review sentiment —\n# replace with exact quotes from their Google listing before launch)\n# ---------------------------------------------------------------\nREVIEWS = [\n    {"name": "Kayla R.",   "text": "The lattes here are really, really good. Grandma\'s Cookies is dangerous — I get one every morning now."},\n    {"name": "Mike T.",    "text": "Friendly service, great coffee, small-town gem. You will enjoy the atmosphere every single time."},\n    {"name": "Jess H.",    "text": "They have new items all the time. Follow them on Facebook or you\'ll miss the good stuff."},\n    {"name": "Dana W.",    "text": "Best coffee stop between Pryor and Tulsa, and it\'s not close. The fruit teas are unreal."},\n    {"name": "Cody B.",    "text": "Stopped in while working in the area — happy to find a real dedicated coffee shop out here."},\n    {"name": "Amber L.",   "text": "They catered our event and everyone was still talking about the coffee a week later."},\n    {"name": "Travis M.",  "text": "Iced caramel. That\'s it. That\'s the review. Yummm."},\n    {"name": "Shelby K.",  "text": "Largest coffee menu I\'ve seen anywhere, and somehow everything I\'ve tried is a hit."},\n]\n\n# ---------------------------------------------------------------\n# GALLERY (placeholders — save real photos from their Facebook page,\n# drop them in static/img/, and update the filenames below)\n# ---------------------------------------------------------------\nGALLERY = [\n    {"src": "img/photos/iced-mocha.jpg", "alt": "Iced mocha with chocolate drizzle from Sweet Bean Canteen", "cap": "The iced mocha, doing numbers"},\n    {"src": "img/photos/sherbet-float.jpg", "alt": "Rainbow sherbet float from Sweet Bean Canteen", "cap": "Sherbet float — summer special"},\n    {"src": "img/photos/croissant-sandwich.jpg", "alt": "Chicken salad croissant sandwich", "cap": "Croissant sandwiches, built to order"},\n]\n\n# ---------------------------------------------------------------\n# EVENTS + BLOCKED DAYS (demo data — this becomes the owner-managed\n# calendar in the real build)\n#   EVENTS: where the trailer will be on a given date (public)\n#   BLOCKED: dates unavailable for event/catering bookings\n# ---------------------------------------------------------------\ndef gallery_items():\n    """Drop real photos (saved from their Facebook page) into\n    static/img/gallery/ and they automatically replace the placeholders\n    below — no code changes needed."""\n    folder = os.path.join(app.static_folder, "img", "gallery")\n    if os.path.isdir(folder):\n        exts = (".jpg", ".jpeg", ".png", ".webp")\n        real = sorted(f for f in os.listdir(folder) if f.lower().endswith(exts))\n        if real:\n            return [{"src": "img/gallery/" + f, "alt": "Sweet Bean Canteen"} for f in real]\n    return GALLERY\n\n\n@app.route("/")\ndef home():\n    return render_template(\n        "index.html",\n        biz=BUSINESS,\n        menu=MENU,\n        reviews=REVIEWS,\n        events=models.all_events()[:4],\n        gallery=gallery_items(),\n    )\n\n\n@app.route("/events")\ndef events():\n    try:\n        year = int(request.args.get("y", date.today().year))\n        month = int(request.args.get("m", date.today().month))\n        date(year, month, 1)\n    except (ValueError, TypeError):\n        year, month = date.today().year, date.today().month\n\n    cal = calendar.Calendar(firstweekday=6)\n    weeks = cal.monthdayscalendar(year, month)\n    month_events = models.events_for_month(year, month)\n\n    prev_y, prev_m = (year - 1, 12) if month == 1 else (year, month - 1)\n    next_y, next_m = (year + 1, 1) if month == 12 else (year, month + 1)\n\n    return render_template(\n        "events.html",\n        biz=BUSINESS,\n        weeks=weeks,\n        year=year,\n        month=month,\n        month_name=calendar.month_name[month],\n        events=month_events,\n        today=date.today().isoformat(),\n        prev_link=f"/events?y={prev_y}&m={prev_m}",\n        next_link=f"/events?y={next_y}&m={next_m}",\n        iso=lambda d: date(year, month, d).isoformat() if d else "",\n        sent=request.args.get("sent") == "1",\n    )\n\n\n@app.route("/events/request", methods=["POST"])\ndef request_event():\n    name = (request.form.get("name") or "").strip()\n    email = (request.form.get("email") or "").strip()\n    phone = (request.form.get("phone") or "").strip()\n    day = (request.form.get("day") or "").strip()\n    details = (request.form.get("details") or "").strip()\n\n    if not name or not (email or phone):\n        flash("Please add your name and a way to reach you.")\n        return redirect(url_for("events"))\n\n    models.add_request(name, email, phone, day, details)\n    notify_owner({"name": name, "email": email, "phone": phone,\n                  "day": day, "details": details})\n    return redirect(url_for("events", sent="1"))\n\n\n# ---------------------- Owner admin ----------------------\n@app.route("/admin/login", methods=["GET", "POST"])\ndef admin_login():\n    if request.method == "POST":\n        if request.form.get("password") == ADMIN_PASSWORD:\n            session["admin"] = True\n            return redirect(request.args.get("next") or url_for("admin"))\n        flash("Wrong password.")\n    return render_template("admin_login.html", biz=BUSINESS)\n\n\n@app.route("/admin/logout")\ndef admin_logout():\n    session.pop("admin", None)\n    return redirect(url_for("home"))\n\n\n@app.route("/admin")\n@login_required\ndef admin():\n    return render_template(\n        "admin.html",\n        biz=BUSINESS,\n        events=models.all_events(),\n        requests=models.all_requests(),\n        today=date.today().isoformat(),\n    )\n\n\n@app.route("/admin/event/add", methods=["POST"])\n@login_required\ndef admin_add_event():\n    day = (request.form.get("day") or "").strip()\n    title = (request.form.get("title") or "").strip()\n    location = (request.form.get("location") or "").strip()\n    time_text = (request.form.get("time_text") or "").strip()\n    blocked = request.form.get("blocked") == "on"\n    if day and (title or blocked):\n        models.add_event(day, title or "Unavailable", location, time_text, blocked)\n        flash("Saved.")\n    else:\n        flash("A date and a title are required.")\n    return redirect(url_for("admin"))\n\n\n@app.route("/admin/event/<int:event_id>/delete", methods=["POST"])\n@login_required\ndef admin_delete_event(event_id):\n    models.delete_event(event_id)\n    flash("Removed.")\n    return redirect(url_for("admin"))\n\n\nif __name__ == "__main__":\n    app.run(debug=True)\n'
TEXT['models.py'] = '"""\nStorage for events and event requests.\n\nUses Postgres when DATABASE_URL is set (Render), otherwise a local SQLite\nfile for development. Same API either way, so the rest of the app doesn\'t\ncare which one is active.\n"""\nimport os\nfrom datetime import datetime\n\nDATABASE_URL = os.environ.get("DATABASE_URL", "")\nUSE_PG = DATABASE_URL.startswith("postgres")\n\nif USE_PG:\n    import psycopg2\n    import psycopg2.extras\n    # Render sometimes hands out a "postgres://" URL; psycopg2 wants "postgresql://"\n    if DATABASE_URL.startswith("postgres://"):\n        DATABASE_URL = DATABASE_URL.replace("postgres://", "postgresql://", 1)\n    PH = "%s"  # placeholder style\nelse:\n    import sqlite3\n    SQLITE_PATH = os.path.join(os.path.dirname(__file__), "sweetbean.db")\n    PH = "?"\n\n\ndef _connect():\n    if USE_PG:\n        return psycopg2.connect(DATABASE_URL, sslmode="require")\n    conn = sqlite3.connect(SQLITE_PATH)\n    conn.row_factory = sqlite3.Row\n    return conn\n\n\ndef init_db():\n    """Create tables if they don\'t exist, and seed demo events once."""\n    conn = _connect()\n    cur = conn.cursor()\n    if USE_PG:\n        cur.execute("""\n            CREATE TABLE IF NOT EXISTS events (\n                id SERIAL PRIMARY KEY,\n                day DATE NOT NULL,\n                title TEXT NOT NULL,\n                location TEXT DEFAULT \'\',\n                time_text TEXT DEFAULT \'\',\n                blocked BOOLEAN DEFAULT FALSE\n            )\n        """)\n        cur.execute("""\n            CREATE TABLE IF NOT EXISTS requests (\n                id SERIAL PRIMARY KEY,\n                name TEXT NOT NULL,\n                email TEXT DEFAULT \'\',\n                phone TEXT DEFAULT \'\',\n                day DATE,\n                details TEXT DEFAULT \'\',\n                created TIMESTAMP DEFAULT NOW(),\n                handled BOOLEAN DEFAULT FALSE\n            )\n        """)\n    else:\n        cur.execute("""\n            CREATE TABLE IF NOT EXISTS events (\n                id INTEGER PRIMARY KEY AUTOINCREMENT,\n                day TEXT NOT NULL,\n                title TEXT NOT NULL,\n                location TEXT DEFAULT \'\',\n                time_text TEXT DEFAULT \'\',\n                blocked INTEGER DEFAULT 0\n            )\n        """)\n        cur.execute("""\n            CREATE TABLE IF NOT EXISTS requests (\n                id INTEGER PRIMARY KEY AUTOINCREMENT,\n                name TEXT NOT NULL,\n                email TEXT DEFAULT \'\',\n                phone TEXT DEFAULT \'\',\n                day TEXT,\n                details TEXT DEFAULT \'\',\n                created TEXT DEFAULT CURRENT_TIMESTAMP,\n                handled INTEGER DEFAULT 0\n            )\n        """)\n    conn.commit()\n\n    # Seed a few demo events the first time only.\n    cur.execute("SELECT COUNT(*) FROM events")\n    count = cur.fetchone()[0]\n    if count == 0:\n        from datetime import date\n        import calendar as _cal\n        t = date.today()\n        last = _cal.monthrange(t.year, t.month)[1]\n\n        def d(day):\n            return date(t.year, t.month, min(day, last)).isoformat()\n\n        seed = [\n            (d(11), "Chouteau Farmers Market", "119 W Main St, Chouteau", "8 AM - 1 PM", False),\n            (d(18), "MidAmerica Industrial Park", "Pryor, OK", "7 AM - 11 AM", False),\n            (d(25), "Downtown Pop-Up", "Main St, Chouteau", "9 AM - 2 PM", False),\n            (d(14), "Private Event", "Booked", "All day", True),\n        ]\n        for row in seed:\n            cur.execute(\n                f"INSERT INTO events (day, title, location, time_text, blocked) "\n                f"VALUES ({PH},{PH},{PH},{PH},{PH})", row\n            )\n        conn.commit()\n    cur.close()\n    conn.close()\n\n\ndef _norm(row):\n    """Return a plain dict with consistent keys and an ISO day string."""\n    d = dict(row)\n    day = d.get("day")\n    if hasattr(day, "isoformat"):\n        day = day.isoformat()\n    d["day"] = str(day)[:10] if day else ""\n    d["blocked"] = bool(d.get("blocked"))\n    return d\n\n\ndef events_for_month(year, month):\n    """All events in a given month, keyed by ISO date string."""\n    conn = _connect()\n    cur = conn.cursor()\n    prefix = f"{year:04d}-{month:02d}-"\n    if USE_PG:\n        cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)\n        cur.execute(\n            "SELECT * FROM events WHERE to_char(day, \'YYYY-MM-\') = %s ORDER BY day", (prefix,)\n        )\n    else:\n        cur.execute("SELECT * FROM events WHERE day LIKE ? ORDER BY day", (prefix + "%",))\n    rows = [_norm(r) for r in cur.fetchall()]\n    cur.close()\n    conn.close()\n    out = {}\n    for r in rows:\n        out[r["day"]] = r\n    return out\n\n\ndef all_events():\n    """Every event, soonest first — used for the homepage teaser."""\n    conn = _connect()\n    if USE_PG:\n        cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)\n    else:\n        cur = conn.cursor()\n    cur.execute("SELECT * FROM events ORDER BY day")\n    rows = [_norm(r) for r in cur.fetchall()]\n    cur.close()\n    conn.close()\n    return rows\n\n\ndef add_event(day, title, location, time_text, blocked=False):\n    conn = _connect()\n    cur = conn.cursor()\n    cur.execute(\n        f"INSERT INTO events (day, title, location, time_text, blocked) "\n        f"VALUES ({PH},{PH},{PH},{PH},{PH})",\n        (day, title, location, time_text, bool(blocked) if USE_PG else int(blocked)),\n    )\n    conn.commit()\n    cur.close()\n    conn.close()\n\n\ndef delete_event(event_id):\n    conn = _connect()\n    cur = conn.cursor()\n    cur.execute(f"DELETE FROM events WHERE id = {PH}", (event_id,))\n    conn.commit()\n    cur.close()\n    conn.close()\n\n\ndef add_request(name, email, phone, day, details):\n    conn = _connect()\n    cur = conn.cursor()\n    cur.execute(\n        f"INSERT INTO requests (name, email, phone, day, details) "\n        f"VALUES ({PH},{PH},{PH},{PH},{PH})",\n        (name, email, phone, day or None, details),\n    )\n    conn.commit()\n    cur.close()\n    conn.close()\n\n\ndef all_requests():\n    conn = _connect()\n    if USE_PG:\n        cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)\n    else:\n        cur = conn.cursor()\n    cur.execute("SELECT * FROM requests ORDER BY created DESC")\n    rows = [dict(r) for r in cur.fetchall()]\n    cur.close()\n    conn.close()\n    return rows\n'
TEXT['emailer.py'] = '"""\nSends the owner an email when a customer requests an event date.\n\nIf RESEND_API_KEY is set, it sends a real email via Resend (free tier).\nIf not, it just prints the notification to the console so the demo works\nwith zero setup.\n"""\nimport os\nimport json\nimport urllib.request\n\nRESEND_API_KEY = os.environ.get("RESEND_API_KEY", "")\nOWNER_EMAIL = os.environ.get("OWNER_EMAIL", "owner@example.com")\nFROM_EMAIL = os.environ.get("FROM_EMAIL", "Sweet Bean Canteen <onboarding@resend.dev>")\n\n\ndef notify_owner(req):\n    """req is a dict with name, email, phone, day, details."""\n    subject = f"New event request from {req[\'name\']}"\n    body = (\n        f"New event / catering request from the website:\\n\\n"\n        f"Name:    {req[\'name\']}\\n"\n        f"Email:   {req.get(\'email\') or \'-\'}\\n"\n        f"Phone:   {req.get(\'phone\') or \'-\'}\\n"\n        f"Date:    {req.get(\'day\') or \'flexible\'}\\n\\n"\n        f"Details:\\n{req.get(\'details\') or \'-\'}\\n"\n    )\n\n    if not RESEND_API_KEY:\n        print("\\n=== EVENT REQUEST (email not configured) ===")\n        print(body)\n        print("============================================\\n")\n        return False\n\n    payload = json.dumps({\n        "from": FROM_EMAIL,\n        "to": [OWNER_EMAIL],\n        "reply_to": req.get("email") or None,\n        "subject": subject,\n        "text": body,\n    }).encode()\n\n    request = urllib.request.Request(\n        "https://api.resend.com/emails",\n        data=payload,\n        headers={\n            "Authorization": f"Bearer {RESEND_API_KEY}",\n            "Content-Type": "application/json",\n        },\n        method="POST",\n    )\n    try:\n        with urllib.request.urlopen(request, timeout=10) as resp:\n            return resp.status < 300\n    except Exception as e:  # noqa\n        print("Email send failed:", e)\n        return False\n'
TEXT['templates/index.html'] = '<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>{{ biz.name }} — Specialty Coffee in Chouteau, OK</title>\n<meta name="description" content="{{ biz.name }} — specialty coffees, pastries, and brunch in Chouteau, Oklahoma. Available for weddings, catering, and events. {{ biz.tagline }}">\n<link rel="preconnect" href="https://fonts.googleapis.com">\n<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n<link href="https://fonts.googleapis.com/css2?family=Pacifico&family=Jost:wght@400;500;600;700&display=swap" rel="stylesheet">\n<link rel="stylesheet" href="{{ url_for(\'static\', filename=\'css/style.css\') }}">\n</head>\n<body>\n\n<header class="nav">\n  <a class="nav-brand" href="/">SWEET<span>BEAN</span></a>\n  <nav class="nav-links">\n    <a href="#menu">Menu</a>\n    <a href="#about">About</a>\n    <a href="/events">Events</a>\n    <a href="#reviews">Reviews</a>\n    <a href="#visit">Visit</a>\n    <a class="nav-cta" href="#book">Book the trailer</a>\n  </nav>\n</header>\n\n<!-- ============ SCROLL HERO ============ -->\n<section class="hero" id="heroTrack">\n  <div class="hero-inner">\n    <div class="hero-copy">\n      <span class="hero-eyebrow">Coffee &amp; Bistro &middot; Chouteau, OK</span>\n      <h1 class="hero-title">\n        <span class="t1">Sweet Bean</span>\n        <span class="t2">CANTEEN</span>\n      </h1>\n      <p class="hero-sub">{{ biz.tagline }}</p>\n      <div class="hero-actions">\n        <a class="btn" href="{{ biz.doordash }}" target="_blank" rel="noopener">Order on DoorDash</a>\n        <a class="btn btn-ghost" href="/events">Book the trailer</a>\n      </div>\n      <div class="hero-badges">\n        <span class="hero-chip"><b>4.8&#9733;</b> on Google</span>\n        <span class="hero-chip">Weddings + Catering</span>\n        <span class="hero-chip">Brewed on wheels</span>\n      </div>\n    </div>\n\n    <div class="hero-visual">\n      <div class="sticker-stage">\n        <svg class="sticker" viewBox="0 0 340 340" xmlns="http://www.w3.org/2000/svg" aria-label="Sweet Bean Canteen badge">\n          <circle cx="170" cy="170" r="160" fill="#A9D7E8" stroke="#1E1B18" stroke-width="7"/>\n          <circle cx="170" cy="170" r="140" fill="none" stroke="#FDF6EC" stroke-width="3" stroke-dasharray="4 9"/>\n          <g transform="translate(170 96)">\n            <path d="M-24 -14 L-20 22 Q-19 30 -11 30 L11 30 Q19 30 20 22 L24 -14 Z"\n                  fill="#FDF6EC" stroke="#1E1B18" stroke-width="4.5" stroke-linejoin="round"/>\n            <rect x="-28" y="-24" width="56" height="12" rx="6" fill="#1E1B18"/>\n            <path d="M-14 -34 C-18 -42 -12 -46 -14 -54" fill="none" stroke="#1E1B18" stroke-width="4" stroke-linecap="round"/>\n            <path d="M0 -36 C-4 -46 2 -50 0 -60" fill="none" stroke="#1E1B18" stroke-width="4.5" stroke-linecap="round"/>\n            <path d="M14 -34 C10 -42 16 -46 14 -54" fill="none" stroke="#1E1B18" stroke-width="4" stroke-linecap="round"/>\n            <path d="M-24 2 L24 2 L22 16 L-22 16 Z" fill="#5BA8C4" stroke="#1E1B18" stroke-width="3.5"/>\n          </g>\n          <text x="170" y="205" text-anchor="middle" font-family="Pacifico, cursive"\n                font-size="47" fill="#1E1B18">Sweet Bean</text>\n          <text x="170" y="245" text-anchor="middle" font-family="Jost, sans-serif" font-weight="700"\n                font-size="24" letter-spacing="9" fill="#FDF6EC" stroke="#1E1B18" stroke-width="0.8" paint-order="stroke fill">CANTEEN</text>\n          <text x="170" y="282" text-anchor="middle" font-family="Jost, sans-serif" font-weight="600"\n                font-size="13" letter-spacing="3.5" fill="#1E1B18">CHOUTEAU, OK</text>\n        </svg>\n      </div>\n    </div>\n  </div>\n\n  <div class="scroll-hint" id="scrollHint">\n    <span>Scroll on down</span>\n    <div class="scroll-hint-bar"></div>\n  </div>\n</section>\n\n<!-- ============ MARQUEE STRIP ============ -->\n<div class="strip" aria-hidden="true">\n  <div class="strip-inner">\n    {% for i in range(4) %}\n    <span>FRESH BLENDS DAILY</span><i>●</i>\n    <span>CHOUTEAU, OK</span><i>●</i>\n    <span>WEDDINGS + CATERING</span><i>●</i>\n    <span>BREWED ON WHEELS</span><i>●</i>\n    {% endfor %}\n  </div>\n</div>\n\n<!-- ============ WHY ============ -->\n<section class="why">\n  <h2 class="section-title">The biggest coffee menu <em>you\'ll find anywhere.</em></h2>\n  <p class="section-lede">Small-town trailer. Big-league espresso. Always creating new blends — if you haven\'t been in this week, you\'ve already missed something.</p>\n  <div class="why-grid">\n    <div class="why-card reveal">\n      <h3>Always something new</h3>\n      <p>New blends and seasonal drinks drop constantly. Regulars know to check the board — and the Facebook page — before ordering the usual.</p>\n    </div>\n    <div class="why-card reveal">\n      <h3>More than coffee</h3>\n      <p>Pastries, croissant sandwiches, wraps, and brunch platters. Fruit teas made with real fruit for the non-coffee crowd.</p>\n    </div>\n    <div class="why-card reveal">\n      <h3>We come to you</h3>\n      <p>The trailer books weddings, events, and catering across the Chouteau–Pryor–Tulsa area. Check the calendar and grab your date.</p>\n    </div>\n  </div>\n</section>\n\n<!-- ============ ABOUT ============ -->\n<section class="about" id="about">\n  <figure class="about-photo reveal">\n    <img src="{{ url_for(\'static\', filename=\'img/photos/patio.jpg\') }}"\n         alt="Friends gathered on the Sweet Bean Canteen patio in Chouteau" loading="lazy">\n    <figcaption>The patio on Main Street, Chouteau</figcaption>\n  </figure>\n  <div class="about-text reveal">\n    <h2 class="section-title">Coffee &amp; bistro. <em>Parked on Main.</em></h2>\n    <p>Sweet Bean Canteen is Chouteau\'s coffee spot — a full coffee and bistro window at 215 W Main, plus a trailer that hits farmers markets, weddings, and events across the area.</p>\n    <p>It\'s the kind of place where the patio fills up, the menu board changes weekly, and your drink comes with your name on the cup. Regulars know: check the board before you order the usual.</p>\n    <span class="about-fact">Est. Chouteau, OK</span>\n    <span class="about-fact">Open 6 days a week</span>\n    <span class="about-fact">Trailer books events</span>\n  </div>\n</section>\n\n<!-- ============ MENU ============ -->\n<section class="menu" id="menu">\n  <h2 class="section-title section-title-light">Choose your <em>brew</em></h2>\n  <div class="menu-grid">\n    {% for item in menu %}\n    <article class="menu-card reveal">\n      <span class="menu-tag">{{ item.tag }}</span>\n      <h3>{{ item.name }}</h3>\n      <p>{{ item.desc }}</p>\n    </article>\n    {% endfor %}\n  </div>\n  <p class="menu-note">Sizes 16oz &amp; 24oz · Full menu at the window</p>\n</section>\n\n<!-- ============ GALLERY ============ -->\n<section class="gallery" id="gallery">\n  <h2 class="section-title section-title-light">Fresh from the <em>trailer</em></h2>\n  <p class="section-lede">The drinks, the treats, the setup. Come see it in person.</p>\n  <div class="gallery-grid">\n    {% for photo in gallery %}\n    <figure class="gallery-item reveal">\n      <img src="{{ url_for(\'static\', filename=photo.src) }}" alt="{{ photo.alt }}" loading="lazy">\n      {% if photo.cap %}<figcaption>{{ photo.cap }}</figcaption>{% endif %}\n    </figure>\n    {% endfor %}\n  </div>\n  </div>\n</section>\n\n<!-- ============ EVENTS TEASER ============ -->\n<section class="events-teaser" id="book">\n  <div class="events-teaser-text reveal">\n    <h2 class="section-title">Find the trailer. <em>Or book it.</em></h2>\n    <p>See where we\'ll be parked on any given date — farmers markets, pop-ups, and private events. Open dates are up for grabs for weddings and catering.</p>\n    <a class="btn" href="/events">See the calendar</a>\n    <a class="btn btn-ghost" href="{{ biz.phone_href }}">Call {{ biz.phone }}</a>\n  </div>\n  <div class="events-teaser-list reveal">\n    {% for ev in events %}\n    <div class="event-row">\n      <span class="event-date">{{ ev.day[5:] }}</span>\n      <div>\n        <strong>{{ ev.title }}</strong>\n        <span>{{ ev.location }}{% if ev.time_text %} · {{ ev.time_text }}{% endif %}</span>\n      </div>\n    </div>\n    {% else %}\n    <div class="event-row"><div><strong>New dates coming soon</strong><span>Check back or request your own below</span></div></div>\n    {% endfor %}\n  </div>\n</section>\n\n<!-- ============ REVIEWS ============ -->\n<section class="reviews" id="reviews">\n  <h2 class="section-title">Word around <em>town</em></h2>\n  <p class="section-lede">4.8 stars on Google. Folks have opinions about the lattes.</p>\n  <div class="review-marquee">\n  <div class="review-row">\n    {% for r in reviews + reviews %}\n    <figure class="review-card">\n      <div class="review-stars">★★★★★</div>\n      <blockquote>{{ r.text }}</blockquote>\n      <figcaption>— {{ r.name }}</figcaption>\n    </figure>\n    {% endfor %}\n  </div>\n</section>\n\n<!-- ============ VISIT ============ -->\n<section class="visit" id="visit">\n  <div class="visit-info reveal">\n    <h2 class="section-title section-title-light">Come find <em>us</em></h2>\n    <p class="visit-addr">{{ biz.address }}</p>\n    <a class="visit-phone" href="{{ biz.phone_href }}">{{ biz.phone }}</a>\n    <div class="visit-social">\n      <a class="btn" href="{{ biz.doordash }}" target="_blank" rel="noopener">Order on DoorDash</a>\n      <a class="btn btn-ghost" href="{{ biz.facebook }}" target="_blank" rel="noopener">Follow on Facebook</a>\n    </div>\n    <table class="hours">\n      {% for day, hrs in biz.hours %}\n      <tr class="{{ \'closed\' if hrs == \'Closed\' }}"><td>{{ day }}</td><td>{{ hrs }}</td></tr>\n      {% endfor %}\n    </table>\n  </div>\n  <div class="visit-map reveal">\n    <iframe src="{{ biz.map_embed }}" title="Map to {{ biz.name }}" loading="lazy" referrerpolicy="no-referrer-when-downgrade" allowfullscreen></iframe>\n  </div>\n</section>\n\n<footer class="footer">\n  <span class="footer-brand">SWEET<span>BEAN</span> CANTEEN</span>\n  <nav class="footer-links">\n    <a href="{{ biz.facebook }}" target="_blank" rel="noopener">Facebook</a>\n    <a href="{{ biz.doordash }}" target="_blank" rel="noopener">DoorDash</a>\n    <a href="{{ biz.phone_href }}">{{ biz.phone }}</a>\n  </nav>\n  <span>© {{ biz.name }}. All rights reserved.</span>\n  <span class="footer-credit">Site by Preston Scott Systems</span>\n</footer>\n\n<script src="{{ url_for(\'static\', filename=\'js/main.js\') }}"></script>\n</body>\n</html>\n'
TEXT['templates/events.html'] = '<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>Events Calendar — {{ biz.name }}</title>\n<meta name="description" content="See where the {{ biz.name }} trailer will be, and which dates are open for weddings, catering, and events.">\n<link rel="preconnect" href="https://fonts.googleapis.com">\n<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n<link href="https://fonts.googleapis.com/css2?family=Pacifico&family=Jost:wght@400;500;600;700&display=swap" rel="stylesheet">\n<link rel="stylesheet" href="{{ url_for(\'static\', filename=\'css/style.css\') }}">\n</head>\n<body class="page-events">\n\n<header class="nav">\n  <a class="nav-brand" href="/">SWEET<span>BEAN</span></a>\n  <nav class="nav-links">\n    <a href="/#menu">Menu</a>\n    <a href="/events">Events</a>\n    <a href="/#reviews">Reviews</a>\n    <a href="/#visit">Visit</a>\n    <a class="nav-cta" href="{{ biz.phone_href }}">Book the trailer</a>\n  </nav>\n</header>\n\n<main class="cal-wrap">\n  <h1 class="section-title">Where\'s the <em>trailer?</em></h1>\n  <p class="section-lede">Tap a marked day to see where we\'ll be. Open dates are available for weddings, catering, and events — call {{ biz.phone }} to grab one.</p>\n\n  <div class="cal-header">\n    <a class="cal-nav" href="{{ prev_link }}" aria-label="Previous month">&larr;</a>\n    <h2>{{ month_name }} {{ year }}</h2>\n    <a class="cal-nav" href="{{ next_link }}" aria-label="Next month">&rarr;</a>\n  </div>\n\n  <div class="cal-legend">\n    <span><i class="dot dot-event"></i> Trailer on location</span>\n    <span><i class="dot dot-blocked"></i> Booked / unavailable</span>\n    <span><i class="dot dot-open"></i> Open for booking</span>\n  </div>\n\n  <table class="cal">\n    <thead>\n      <tr>\n        <th>Sun</th><th>Mon</th><th>Tue</th><th>Wed</th><th>Thu</th><th>Fri</th><th>Sat</th>\n      </tr>\n    </thead>\n    <tbody>\n      {% for week in weeks %}\n      <tr>\n        {% for day in week %}\n        {% if day == 0 %}\n        <td class="cal-empty"></td>\n        {% else %}\n        {% set key = iso(day) %}\n        {% set ev = events.get(key) %}\n        <td class="cal-day {{ \'is-today\' if key == today }} {{ \'is-blocked\' if ev and ev.blocked }} {{ \'has-event\' if ev and not ev.blocked }}">\n          <span class="cal-num">{{ day }}</span>\n          {% if ev and not ev.blocked %}\n          <div class="cal-event">\n            <strong>{{ ev.title }}</strong>\n            {% if ev.location %}<span>{{ ev.location }}</span>{% endif %}\n            {% if ev.time_text %}<span>{{ ev.time_text }}</span>{% endif %}\n          </div>\n          {% elif ev and ev.blocked %}\n          <span class="cal-badge">Booked</span>\n          {% endif %}\n        </td>\n        {% endif %}\n        {% endfor %}\n      </tr>\n      {% endfor %}\n    </tbody>\n  </table>\n\n  <section class="request" id="request">\n    {% if sent %}\n    <div class="request-success">\n      <h3>Request sent! &#127877;</h3>\n      <p>Thanks &mdash; the Sweet Bean team will reach out soon. For anything urgent, call <a href="{{ biz.phone_href }}">{{ biz.phone }}</a>.</p>\n    </div>\n    {% else %}\n    <h2 class="section-title">Want the trailer at <em>your event?</em></h2>\n    <p class="section-lede">Weddings, parties, church events, company mornings &mdash; tell us the date and we\'ll get back to you.</p>\n    {% with messages = get_flashed_messages() %}\n      {% if messages %}<p class="form-error">{{ messages[0] }}</p>{% endif %}\n    {% endwith %}\n    <form class="request-form" method="POST" action="/events/request">\n      <div class="field"><label>Your name *</label><input name="name" required></div>\n      <div class="field"><label>Email</label><input name="email" type="email" placeholder="you@email.com"></div>\n      <div class="field"><label>Phone</label><input name="phone" placeholder="(918) ___-____"></div>\n      <div class="field"><label>Event date</label><input name="day" type="date"></div>\n      <div class="field field-wide"><label>Tell us about it</label><textarea name="details" rows="4" placeholder="Type of event, location, how many people, what you\'d like..."></textarea></div>\n      <button class="btn" type="submit">Send request</button>\n      <p class="form-note">* Add your name and either email or phone so we can reach you.</p>\n    </form>\n    {% endif %}\n  </section>\n</main>\n\n<footer class="footer">\n  <span class="footer-brand">SWEET<span>BEAN</span> CANTEEN</span>\n  <span>© {{ biz.name }}. All rights reserved.</span>\n  <span class="footer-credit">Site by Preston Scott Systems &middot; <a href="/admin" style="color:inherit;opacity:0.7;">Owner login</a></span>\n</footer>\n\n</body>\n</html>\n'
TEXT['templates/admin.html'] = '<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>Owner Dashboard — {{ biz.name }}</title>\n<link rel="preconnect" href="https://fonts.googleapis.com">\n<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n<link href="https://fonts.googleapis.com/css2?family=Pacifico&family=Jost:wght@400;500;600;700&display=swap" rel="stylesheet">\n<link rel="stylesheet" href="{{ url_for(\'static\', filename=\'css/style.css\') }}">\n</head>\n<body class="page-admin">\n\n<header class="admin-nav">\n  <a class="admin-brand" href="/">SWEET<span>BEAN</span> <small>Owner Dashboard</small></a>\n  <div>\n    <a href="/" class="admin-link">View site</a>\n    <a href="/admin/logout" class="admin-link">Log out</a>\n  </div>\n</header>\n\n<main class="admin-wrap">\n  {% with messages = get_flashed_messages() %}\n    {% if messages %}<div class="admin-flash">{{ messages[0] }}</div>{% endif %}\n  {% endwith %}\n\n  <div class="admin-grid">\n    <!-- Add / schedule -->\n    <section class="admin-card">\n      <h2>Add an event or block a date</h2>\n      <p class="admin-hint">Add where the trailer will be, or check "block this date" to mark yourself unavailable. Changes show on the website instantly.</p>\n      <form method="POST" action="/admin/event/add" class="admin-form">\n        <label>Date</label>\n        <input name="day" type="date" value="{{ today }}" required>\n        <label>Title</label>\n        <input name="title" placeholder="Farmers Market, Private Wedding, etc.">\n        <label>Location</label>\n        <input name="location" placeholder="Main St, Chouteau">\n        <label>Time</label>\n        <input name="time_text" placeholder="8 AM - 1 PM">\n        <label class="admin-check"><input name="blocked" type="checkbox"> Block this date (unavailable for bookings)</label>\n        <button class="btn" type="submit">Save to calendar</button>\n      </form>\n    </section>\n\n    <!-- Upcoming events -->\n    <section class="admin-card">\n      <h2>Scheduled ({{ events|length }})</h2>\n      {% if events %}\n      <ul class="admin-list">\n        {% for ev in events %}\n        <li>\n          <div>\n            <strong>{{ ev.day }}</strong>\n            {% if ev.blocked %}<span class="tag tag-blocked">Blocked</span>{% endif %}\n            <span>{{ ev.title }}{% if ev.location %} · {{ ev.location }}{% endif %}{% if ev.time_text %} · {{ ev.time_text }}{% endif %}</span>\n          </div>\n          <form method="POST" action="/admin/event/{{ ev.id }}/delete" onsubmit="return confirm(\'Remove this?\');">\n            <button class="admin-del" type="submit">&times;</button>\n          </form>\n        </li>\n        {% endfor %}\n      </ul>\n      {% else %}\n      <p class="admin-empty">Nothing scheduled yet.</p>\n      {% endif %}\n    </section>\n  </div>\n\n  <!-- Requests inbox -->\n  <section class="admin-card admin-card-full">\n    <h2>Event requests ({{ requests|length }})</h2>\n    {% if requests %}\n    <table class="admin-table">\n      <thead><tr><th>When</th><th>Name</th><th>Contact</th><th>Date</th><th>Details</th></tr></thead>\n      <tbody>\n        {% for r in requests %}\n        <tr>\n          <td>{{ r.created }}</td>\n          <td>{{ r.name }}</td>\n          <td>\n            {% if r.email %}<a href="mailto:{{ r.email }}">{{ r.email }}</a><br>{% endif %}\n            {% if r.phone %}<a href="tel:{{ r.phone }}">{{ r.phone }}</a>{% endif %}\n          </td>\n          <td>{{ r.day or \'—\' }}</td>\n          <td>{{ r.details }}</td>\n        </tr>\n        {% endfor %}\n      </tbody>\n    </table>\n    {% else %}\n    <p class="admin-empty">No requests yet. They\'ll show up here (and in the owner\'s email) when customers submit the form.</p>\n    {% endif %}\n  </section>\n</main>\n</body>\n</html>\n'
TEXT['templates/admin_login.html'] = '<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>Owner Login — {{ biz.name }}</title>\n<link rel="preconnect" href="https://fonts.googleapis.com">\n<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n<link href="https://fonts.googleapis.com/css2?family=Pacifico&family=Jost:wght@400;500;600;700&display=swap" rel="stylesheet">\n<link rel="stylesheet" href="{{ url_for(\'static\', filename=\'css/style.css\') }}">\n</head>\n<body class="page-admin">\n<div class="admin-login">\n  <a class="admin-brand" href="/">SWEET<span>BEAN</span></a>\n  <h1>Owner Login</h1>\n  {% with messages = get_flashed_messages() %}\n    {% if messages %}<p class="form-error">{{ messages[0] }}</p>{% endif %}\n  {% endwith %}\n  <form method="POST">\n    <div class="field"><label>Password</label><input name="password" type="password" autofocus required></div>\n    <button class="btn" type="submit">Log in</button>\n  </form>\n  <a class="admin-back" href="/">&larr; Back to site</a>\n</div>\n</body>\n</html>\n'
TEXT['static/css/style.css'] = '/* ================================================================\n   SWEET BEAN CANTEEN — v7 "The Sticker"\n   Built from their real cup label: powder-blue badge, script logo,\n   cream paper, ink linework, checkerboard from the counter.\n   Fonts: Pacifico (script) + Jost (clean sans)\n   ================================================================ */\n:root {\n  --cream: #FDF6EC;\n  --cream-deep: #F4E7D3;\n  --blue: #A9D7E8;\n  --blue-deep: #5BA8C4;\n  --blue-dark: #2E7D9C;\n  --blue-mist: #E4F2F8;\n  --ink: #1E1B18;\n  --espresso: #3E2C22;\n  --espresso-soft: #7A5C42;\n  --script: "Pacifico", cursive;\n  --sans: "Jost", "Segoe UI", sans-serif;\n  --r-sm: 10px;\n  --r-md: 16px;\n  --r-lg: 24px;\n  --line: 3px solid var(--ink);\n  --shadow-sticker: 5px 6px 0 rgba(30, 27, 24, 0.9);\n  --shadow-soft: 0 10px 26px rgba(62, 44, 34, 0.14);\n  --checker: repeating-linear-gradient(90deg, var(--ink) 0 14px, var(--cream) 14px 28px);\n}\n\n* { margin: 0; padding: 0; box-sizing: border-box; }\nhtml { scroll-behavior: smooth; }\nbody {\n  font-family: var(--sans);\n  font-weight: 400;\n  background: var(--cream);\n  color: var(--espresso);\n  line-height: 1.65;\n  overflow-x: hidden;\n}\nimg, svg { display: block; max-width: 100%; }\na { color: inherit; text-decoration: none; }\n\n/* ---------------- NAV ---------------- */\n.nav {\n  position: fixed;\n  top: 0; left: 0; right: 0;\n  z-index: 50;\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  padding: 12px 5vw;\n  background: rgba(253, 246, 236, 0.94);\n  backdrop-filter: blur(10px);\n  border-bottom: var(--line);\n}\n.nav-brand {\n  font-family: var(--script);\n  font-size: 1.5rem;\n  color: var(--ink);\n}\n.nav-brand span { color: var(--blue-deep); }\n.nav-links { display: flex; align-items: center; gap: 26px; }\n.nav-links a {\n  font-weight: 600;\n  font-size: 0.82rem;\n  text-transform: uppercase;\n  letter-spacing: 0.12em;\n  color: var(--ink);\n  transition: color 0.15s;\n}\n.nav-links a:hover { color: var(--blue-dark); }\n.nav-cta {\n  background: var(--ink);\n  color: var(--cream) !important;\n  padding: 10px 20px;\n  border-radius: 6px;\n  border: 2px solid var(--ink);\n  transition: background 0.15s, color 0.15s, transform 0.15s;\n}\n.nav-cta:hover { background: var(--blue); color: var(--ink) !important; transform: translateY(-2px); }\n\n/* ---------------- HERO ---------------- */\n.hero {\n  position: relative;\n  min-height: 100vh;\n  display: flex;\n  align-items: center;\n  padding: 120px 5vw 90px;\n  background: var(--cream);\n}\n.hero::before {\n  content: "";\n  position: absolute;\n  inset: 0;\n  background-image: radial-gradient(rgba(62, 44, 34, 0.07) 1.5px, transparent 1.5px);\n  background-size: 26px 26px;\n  pointer-events: none;\n}\n.hero-inner {\n  position: relative;\n  width: 100%;\n  max-width: 1140px;\n  margin: 0 auto;\n  display: grid;\n  grid-template-columns: 1.1fr 0.9fr;\n  gap: 48px;\n  align-items: center;\n}\n.hero-eyebrow {\n  display: inline-block;\n  background: var(--cream);\n  border: 2px solid var(--ink);\n  color: var(--ink);\n  font-weight: 600;\n  font-size: 0.76rem;\n  text-transform: uppercase;\n  letter-spacing: 0.16em;\n  padding: 7px 16px;\n  border-radius: 6px;\n  box-shadow: 3px 3px 0 var(--blue);\n  transform: rotate(-1deg);\n}\n.hero-title { margin: 26px 0 0; line-height: 1; }\n.hero-title .t1 {\n  display: block;\n  font-family: var(--script);\n  font-size: clamp(3.2rem, 7.5vw, 6.2rem);\n  color: var(--blue-deep);\n  text-shadow: 3px 3px 0 rgba(30, 27, 24, 0.12);\n}\n.hero-title .t2 {\n  display: block;\n  font-family: var(--sans);\n  font-weight: 700;\n  font-size: clamp(2.2rem, 5.4vw, 4.4rem);\n  letter-spacing: 0.22em;\n  color: var(--ink);\n  margin-top: 8px;\n}\n.hero-sub {\n  margin-top: 20px;\n  font-size: clamp(1rem, 1.8vw, 1.2rem);\n  font-weight: 500;\n  color: var(--espresso);\n  max-width: 470px;\n}\n.hero-actions { margin-top: 28px; display: flex; flex-wrap: wrap; gap: 14px; }\n.hero-actions .btn { margin: 0; }\n.hero-badges { margin-top: 28px; display: flex; flex-wrap: wrap; gap: 12px; }\n.hero-chip {\n  background: var(--cream);\n  border: 2px solid var(--ink);\n  color: var(--ink);\n  font-weight: 600;\n  font-size: 0.78rem;\n  text-transform: uppercase;\n  letter-spacing: 0.06em;\n  padding: 8px 14px;\n  border-radius: 6px;\n}\n.hero-chip:nth-child(1) { transform: rotate(-1.5deg); box-shadow: 3px 3px 0 var(--blue); }\n.hero-chip:nth-child(2) { transform: rotate(1deg); box-shadow: 3px 3px 0 var(--cream-deep); }\n.hero-chip:nth-child(3) { transform: rotate(-0.5deg); box-shadow: 3px 3px 0 var(--blue); }\n.hero-chip b { color: var(--blue-dark); }\n\n.hero-visual { display: flex; justify-content: center; }\n.sticker-stage {\n  transform: rotate(-4deg);\n  animation: floatIdle 6s ease-in-out infinite;\n}\n@keyframes floatIdle {\n  0%, 100% { transform: rotate(-4deg) translateY(0); }\n  50% { transform: rotate(-3deg) translateY(-12px); }\n}\n.sticker {\n  width: clamp(280px, 34vw, 430px);\n  height: auto;\n  filter: drop-shadow(10px 12px 0 rgba(30, 27, 24, 0.85));\n}\n\n.scroll-hint {\n  position: absolute;\n  bottom: 26px;\n  left: 50%;\n  transform: translateX(-50%);\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 8px;\n  font-size: 0.72rem;\n  font-weight: 600;\n  text-transform: uppercase;\n  letter-spacing: 0.16em;\n  color: var(--ink);\n}\n.scroll-hint-bar {\n  width: 3px; height: 38px;\n  background: var(--ink);\n  animation: hintPulse 1.4s ease-in-out infinite;\n}\n@keyframes hintPulse {\n  0%, 100% { transform: scaleY(1); opacity: 1; }\n  50% { transform: scaleY(0.5); opacity: 0.4; }\n}\n\n/* ---------------- MARQUEE STRIP (checkerboard framed) ---------------- */\n.strip {\n  background: var(--ink);\n  color: var(--cream);\n  overflow: hidden;\n  padding: 13px 0;\n  border-top: 10px solid transparent;\n  border-bottom: 10px solid transparent;\n  border-image: var(--checker) 10;\n}\n.strip-inner {\n  display: flex;\n  align-items: center;\n  gap: 34px;\n  white-space: nowrap;\n  width: max-content;\n  animation: marquee 26s linear infinite;\n  font-weight: 600;\n  font-size: 0.95rem;\n  letter-spacing: 0.16em;\n  padding-right: 34px;\n}\n.strip-inner i { color: var(--blue); font-style: normal; }\n@keyframes marquee {\n  from { transform: translateX(0); }\n  to { transform: translateX(-25%); }\n}\n\n/* ---------------- SECTION BASICS ---------------- */\n.section-title {\n  font-family: var(--sans);\n  font-weight: 700;\n  font-size: clamp(1.9rem, 4.4vw, 3.2rem);\n  line-height: 1.12;\n  letter-spacing: 0.01em;\n  color: var(--ink);\n}\n.section-title em {\n  font-style: normal;\n  font-family: var(--script);\n  font-weight: 400;\n  color: var(--blue-deep);\n  letter-spacing: 0;\n}\n.section-title-light { color: var(--cream); }\n.section-title-light em { color: var(--blue); }\n.section-lede {\n  margin-top: 14px;\n  max-width: 580px;\n  font-size: 1.02rem;\n  font-weight: 500;\n}\n\n/* ---------------- WHY ---------------- */\n.why { padding: 100px 5vw; background: var(--blue-mist); }\n.why-grid {\n  margin-top: 48px;\n  display: grid;\n  grid-template-columns: repeat(3, 1fr);\n  gap: 24px;\n}\n.why-card {\n  background: var(--cream);\n  border: var(--line);\n  border-radius: var(--r-md);\n  padding: 32px 28px;\n  box-shadow: var(--shadow-sticker);\n  transition: transform 0.18s;\n}\n.why-card:hover { transform: translate(-3px, -4px) rotate(-0.4deg); }\n.why-card h3 {\n  font-family: var(--script);\n  font-size: 1.5rem;\n  margin-bottom: 10px;\n  color: var(--blue-dark);\n}\n.why-card p { font-size: 0.95rem; }\n\n/* ---------------- ABOUT ---------------- */\n.about {\n  padding: 100px 5vw;\n  background: var(--cream);\n  display: grid;\n  grid-template-columns: 1.05fr 1fr;\n  gap: 56px;\n  align-items: center;\n}\n.about-photo { transform: rotate(-1.5deg); }\n.about-photo img {\n  width: 100%;\n  height: 420px;\n  object-fit: cover;\n  border: 10px solid #FFFFFF;\n  outline: var(--line);\n  border-radius: 4px;\n  box-shadow: var(--shadow-sticker);\n}\n.about-photo figcaption {\n  margin-top: 16px;\n  text-align: center;\n  font-family: var(--script);\n  font-size: 1.05rem;\n  color: var(--espresso-soft);\n}\n.about-text p { margin-top: 18px; max-width: 560px; font-weight: 500; }\n.about-fact {\n  display: inline-block;\n  margin-top: 22px;\n  margin-right: 12px;\n  background: var(--blue);\n  border: 2px solid var(--ink);\n  color: var(--ink);\n  border-radius: 6px;\n  padding: 8px 16px;\n  font-weight: 600;\n  font-size: 0.78rem;\n  text-transform: uppercase;\n  letter-spacing: 0.08em;\n}\n.about-fact:nth-of-type(2) { background: var(--cream-deep); transform: rotate(1deg); }\n.about-fact:nth-of-type(3) { transform: rotate(-1deg); }\n\n/* ---------------- MENU ---------------- */\n.menu { background: var(--espresso); color: var(--cream); padding: 100px 5vw; }\n.menu-grid {\n  margin-top: 48px;\n  display: grid;\n  grid-template-columns: repeat(4, 1fr);\n  gap: 22px;\n}\n.menu-card {\n  background: var(--cream);\n  color: var(--espresso);\n  border: var(--line);\n  border-radius: var(--r-md);\n  padding: 28px 24px;\n  min-height: 220px;\n  display: flex;\n  flex-direction: column;\n  box-shadow: 5px 6px 0 rgba(0, 0, 0, 0.35);\n  transition: transform 0.18s;\n}\n.menu-card:hover { transform: translate(-3px, -4px) rotate(-0.5deg); }\n.menu-card:nth-child(even):hover { transform: translate(-3px, -4px) rotate(0.5deg); }\n.menu-tag {\n  font-size: 0.68rem;\n  font-weight: 600;\n  text-transform: uppercase;\n  letter-spacing: 0.14em;\n  color: var(--blue-dark);\n  margin-bottom: auto;\n}\n.menu-card h3 {\n  font-family: var(--script);\n  font-size: 1.45rem;\n  line-height: 1.2;\n  margin: 16px 0 8px;\n  color: var(--ink);\n}\n.menu-card p { font-size: 0.9rem; }\n.menu-note {\n  margin-top: 36px;\n  text-align: center;\n  font-size: 0.8rem;\n  font-weight: 600;\n  opacity: 0.8;\n  text-transform: uppercase;\n  letter-spacing: 0.14em;\n}\n\n/* ---------------- GALLERY (polaroid wall) ---------------- */\n.gallery { padding: 100px 5vw; background: var(--cream-deep); }\n.gallery-grid {\n  margin-top: 52px;\n  display: grid;\n  grid-template-columns: repeat(3, 1fr);\n  gap: 34px;\n}\n.gallery-item {\n  background: #FFFFFF;\n  border: var(--line);\n  border-radius: 4px;\n  padding: 12px 12px 16px;\n  box-shadow: var(--shadow-sticker);\n  transition: transform 0.18s;\n}\n.gallery-item:nth-child(1) { transform: rotate(-2deg); }\n.gallery-item:nth-child(2) { transform: rotate(1.4deg); }\n.gallery-item:nth-child(3) { transform: rotate(-1deg); }\n.gallery-item:hover { transform: rotate(0deg) translateY(-6px); }\n.gallery-item img {\n  width: 100%;\n  height: 320px;\n  object-fit: cover;\n  border-radius: 2px;\n}\n.gallery-item figcaption {\n  padding: 14px 4px 0;\n  text-align: center;\n  font-family: var(--script);\n  font-size: 1.05rem;\n  color: var(--espresso);\n}\n\n/* ---------------- EVENTS TEASER ---------------- */\n.events-teaser {\n  padding: 100px 5vw;\n  display: grid;\n  grid-template-columns: 1.1fr 1fr;\n  gap: 60px;\n  align-items: center;\n  background: var(--blue);\n  border-top: var(--line);\n  border-bottom: var(--line);\n}\n.events-teaser .section-lede { color: var(--ink); }\n.btn {\n  display: inline-block;\n  margin-top: 26px;\n  margin-right: 14px;\n  background: var(--ink);\n  color: var(--cream);\n  font-weight: 600;\n  text-transform: uppercase;\n  letter-spacing: 0.1em;\n  font-size: 0.86rem;\n  padding: 14px 28px;\n  border: 2px solid var(--ink);\n  border-radius: 8px;\n  box-shadow: 4px 5px 0 rgba(30, 27, 24, 0.35);\n  transition: transform 0.15s, background 0.15s, color 0.15s, box-shadow 0.15s;\n}\n.btn:hover { transform: translate(-2px, -3px); box-shadow: 6px 7px 0 rgba(30, 27, 24, 0.4); }\n.btn-ghost { background: var(--cream); color: var(--ink); }\n.btn-ghost:hover { background: #FFFFFF; }\n.events-teaser-list { display: flex; flex-direction: column; gap: 14px; }\n.event-row {\n  display: flex;\n  align-items: center;\n  gap: 20px;\n  background: var(--cream);\n  border: var(--line);\n  border-radius: var(--r-sm);\n  padding: 16px 20px;\n  box-shadow: 4px 5px 0 rgba(30, 27, 24, 0.55);\n}\n.event-date {\n  font-family: var(--script);\n  font-size: 1.2rem;\n  color: var(--blue-dark);\n  min-width: 72px;\n}\n.event-row strong { display: block; color: var(--ink); }\n.event-row span:not(.event-date) { font-size: 0.85rem; color: var(--espresso-soft); }\n\n/* ---------------- REVIEWS (marquee) ---------------- */\n.reviews { padding: 100px 0 110px; background: var(--ink); color: var(--cream); overflow: hidden; }\n.reviews .section-title, .reviews .section-lede { padding: 0 5vw; }\n.reviews .section-title { color: var(--cream); }\n.reviews .section-title em { color: var(--blue); }\n.review-marquee { margin-top: 50px; overflow: hidden; }\n.review-row {\n  display: flex;\n  gap: 24px;\n  width: max-content;\n  animation: marqueeHalf 60s linear infinite;\n  padding: 8px 0 14px;\n}\n.review-row:hover { animation-play-state: paused; }\n@keyframes marqueeHalf {\n  from { transform: translateX(0); }\n  to { transform: translateX(-50%); }\n}\n.review-card {\n  width: 350px;\n  flex-shrink: 0;\n  background: var(--cream);\n  color: var(--espresso);\n  border: var(--line);\n  border-radius: var(--r-sm);\n  padding: 26px 24px;\n  box-shadow: 5px 6px 0 rgba(169, 215, 232, 0.5);\n}\n.review-row .review-card:nth-child(odd) { transform: rotate(-0.6deg); }\n.review-row .review-card:nth-child(even) { transform: rotate(0.6deg); }\n.review-stars { color: var(--blue-dark); letter-spacing: 0.2em; margin-bottom: 12px; }\n.review-card blockquote { font-size: 0.95rem; font-weight: 500; }\n.review-card figcaption {\n  margin-top: 14px;\n  font-family: var(--script);\n  font-size: 1rem;\n  color: var(--blue-dark);\n}\n\n/* ---------------- VISIT ---------------- */\n.visit {\n  background: var(--espresso);\n  color: var(--cream);\n  padding: 100px 5vw;\n  display: grid;\n  grid-template-columns: 1fr 1.2fr;\n  gap: 60px;\n}\n.visit .section-title { color: var(--cream); }\n.visit .section-title em { color: var(--blue); }\n.visit-addr { margin-top: 24px; font-size: 1.08rem; font-weight: 600; }\n.visit-phone {\n  display: inline-block;\n  margin-top: 6px;\n  color: var(--blue);\n  font-weight: 600;\n  font-size: 1.08rem;\n}\n.visit-phone:hover { text-decoration: underline; }\n.visit-social { margin-top: 8px; }\n.visit-social .btn { background: var(--cream); color: var(--ink); border-color: var(--cream); }\n.visit-social .btn.btn-ghost { background: transparent; color: var(--cream); border-color: var(--cream); box-shadow: 4px 5px 0 rgba(0,0,0,0.3); }\n.hours { margin-top: 28px; border-collapse: collapse; width: 100%; max-width: 380px; }\n.hours td { padding: 9px 0; border-bottom: 1px dashed rgba(253, 246, 236, 0.35); font-size: 0.95rem; font-weight: 500; }\n.hours td:last-child { text-align: right; }\n.hours tr.closed td { opacity: 0.5; }\n.visit-map {\n  border: 10px solid #FFFFFF;\n  outline: var(--line);\n  border-radius: 4px;\n  overflow: hidden;\n  box-shadow: var(--shadow-sticker);\n  min-height: 400px;\n  transform: rotate(0.8deg);\n}\n.visit-map iframe { width: 100%; height: 100%; min-height: 400px; border: 0; }\n\n/* ---------------- FOOTER ---------------- */\n.footer {\n  background: var(--ink);\n  color: var(--cream);\n  border-top: 10px solid transparent;\n  border-image: var(--checker) 10;\n  padding: 30px 5vw;\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  gap: 16px;\n  flex-wrap: wrap;\n  font-size: 0.85rem;\n  font-weight: 500;\n}\n.footer-brand { font-family: var(--script); font-size: 1.15rem; }\n.footer-brand span { color: var(--blue); }\n.footer-links { display: flex; gap: 20px; }\n.footer-links a { color: var(--blue); font-weight: 600; transition: color 0.15s; }\n.footer-links a:hover { color: var(--cream); }\n.footer-credit { opacity: 0.55; }\n\n/* ---------------- SCROLL REVEALS ---------------- */\n.reveal { opacity: 0; transform: translateY(24px); transition: opacity 0.6s ease, transform 0.6s ease; }\n.reveal.is-in { opacity: 1; transform: none; }\n\n/* ---------------- EVENTS PAGE / CALENDAR ---------------- */\n.page-events { background: var(--cream); }\n.cal-wrap { max-width: 1080px; margin: 0 auto; padding: 140px 5vw 90px; }\n.cal-header { display: flex; align-items: center; justify-content: space-between; margin-top: 44px; }\n.cal-header h2 { font-family: var(--script); font-size: 1.9rem; color: var(--ink); }\n.cal-nav {\n  font-size: 1.2rem;\n  font-weight: 600;\n  background: var(--cream);\n  border: var(--line);\n  border-radius: 8px;\n  padding: 6px 20px;\n  box-shadow: 3px 4px 0 var(--blue);\n  transition: transform 0.15s;\n}\n.cal-nav:hover { transform: translate(-2px, -2px); }\n.cal-legend { display: flex; gap: 24px; flex-wrap: wrap; margin-top: 18px; font-size: 0.85rem; font-weight: 600; }\n.dot { display: inline-block; width: 12px; height: 12px; margin-right: 6px; border: 2px solid var(--ink); border-radius: 3px; }\n.dot-event { background: var(--blue); }\n.dot-blocked { background: var(--ink); }\n.dot-open { background: #FFFFFF; }\n.cal {\n  width: 100%;\n  margin-top: 18px;\n  border-collapse: separate;\n  border-spacing: 0;\n  background: #FFFFFF;\n  border: var(--line);\n  border-radius: var(--r-md);\n  overflow: hidden;\n  box-shadow: var(--shadow-sticker);\n  table-layout: fixed;\n}\n.cal th {\n  background: var(--ink);\n  color: var(--cream);\n  padding: 12px 0;\n  font-size: 0.76rem;\n  font-weight: 600;\n  text-transform: uppercase;\n  letter-spacing: 0.12em;\n}\n.cal td {\n  border: 1px solid rgba(30, 27, 24, 0.12);\n  vertical-align: top;\n  height: 106px;\n  padding: 8px;\n}\n.cal-num { font-weight: 600; font-size: 0.9rem; color: var(--ink); }\n.cal-empty { background: var(--cream); }\n.cal-day.is-today .cal-num {\n  background: var(--blue);\n  border: 2px solid var(--ink);\n  border-radius: 6px;\n  padding: 2px 8px;\n  display: inline-block;\n}\n.cal-day.has-event { background: var(--blue-mist); }\n.cal-event { margin-top: 6px; font-size: 0.72rem; line-height: 1.35; font-weight: 500; }\n.cal-event strong { display: block; font-size: 0.76rem; color: var(--ink); }\n.cal-event span { display: block; color: var(--espresso-soft); }\n.cal-day.is-blocked { background: var(--ink); color: var(--cream); }\n.cal-badge {\n  display: inline-block;\n  margin-top: 8px;\n  font-size: 0.64rem;\n  font-weight: 600;\n  text-transform: uppercase;\n  letter-spacing: 0.12em;\n  color: var(--blue);\n}\n\n/* ---------------- REQUEST FORM ---------------- */\n.request {\n  max-width: 780px;\n  margin: 64px auto 0;\n  background: #FFFFFF;\n  border: var(--line);\n  border-radius: var(--r-md);\n  box-shadow: var(--shadow-sticker);\n  padding: 44px 40px;\n}\n.request-form { margin-top: 24px; display: grid; grid-template-columns: 1fr 1fr; gap: 18px; }\n.request-form .field { display: flex; flex-direction: column; }\n.request-form .field-wide { grid-column: 1 / -1; }\n.request-form label { font-weight: 600; font-size: 0.8rem; text-transform: uppercase; letter-spacing: 0.08em; margin-bottom: 6px; color: var(--blue-dark); }\n.request-form input,\n.request-form textarea {\n  font-family: var(--sans);\n  font-weight: 400;\n  font-size: 1rem;\n  padding: 12px 14px;\n  border: 2px solid var(--ink);\n  border-radius: 8px;\n  background: var(--cream);\n  transition: box-shadow 0.15s;\n}\n.request-form input:focus,\n.request-form textarea:focus { outline: none; box-shadow: 3px 3px 0 var(--blue); }\n.request-form .btn { grid-column: 1 / -1; justify-self: start; }\n.form-note { grid-column: 1 / -1; font-size: 0.8rem; opacity: 0.65; margin-top: -4px; }\n.form-error { background: #FBE9E7; border: 2px solid #B23A2E; color: #B23A2E; font-weight: 600; padding: 10px 16px; border-radius: 8px; margin-top: 12px; }\n.request-success { text-align: center; padding: 20px; }\n.request-success h3 { font-family: var(--script); font-size: 2rem; color: var(--blue-dark); }\n.request-success p { margin-top: 10px; font-weight: 500; }\n.request-success a { color: var(--blue-dark); font-weight: 600; }\n.cal-cta { margin-top: 44px; text-align: center; font-size: 1.05rem; font-weight: 600; }\n\n/* ---------------- ADMIN ---------------- */\n.page-admin { background: var(--cream); min-height: 100vh; }\n.admin-login {\n  max-width: 380px;\n  margin: 10vh auto;\n  background: #FFFFFF;\n  border: var(--line);\n  border-radius: var(--r-md);\n  box-shadow: var(--shadow-sticker);\n  padding: 44px 40px;\n  text-align: center;\n}\n.admin-brand { font-family: var(--script); font-size: 1.4rem; color: var(--ink); }\n.admin-brand span { color: var(--blue-deep); }\n.admin-brand small { font-family: var(--sans); font-weight: 600; font-size: 0.68rem; opacity: 0.6; letter-spacing: 0.08em; text-transform: uppercase; }\n.admin-login h1 { font-weight: 700; font-size: 1.5rem; margin: 20px 0 18px; color: var(--ink); }\n.admin-login .field { text-align: left; display: flex; flex-direction: column; margin-bottom: 18px; }\n.admin-login label { font-weight: 600; font-size: 0.8rem; text-transform: uppercase; letter-spacing: 0.08em; margin-bottom: 6px; color: var(--blue-dark); }\n.admin-login input { font-family: var(--sans); font-size: 1rem; padding: 12px 14px; border: 2px solid var(--ink); border-radius: 8px; background: var(--cream); }\n.admin-login input:focus { outline: none; box-shadow: 3px 3px 0 var(--blue); }\n.admin-login .btn { width: 100%; text-align: center; margin-right: 0; }\n.admin-back { display: inline-block; margin-top: 18px; font-weight: 600; font-size: 0.85rem; color: var(--blue-dark); }\n.admin-nav { display: flex; justify-content: space-between; align-items: center; background: var(--ink); color: var(--cream); padding: 14px 5vw; border-bottom: 8px solid transparent; border-image: var(--checker) 8; }\n.admin-nav .admin-brand { color: var(--cream); }\n.admin-link { color: var(--blue); font-weight: 600; font-size: 0.82rem; text-transform: uppercase; letter-spacing: 0.08em; margin-left: 22px; }\n.admin-link:hover { color: var(--cream); }\n.admin-wrap { max-width: 1100px; margin: 0 auto; padding: 40px 5vw 80px; }\n.admin-flash { background: #E7F6EA; border: 2px solid #2E7D46; color: #2E7D46; font-weight: 600; padding: 12px 18px; border-radius: 8px; margin-bottom: 22px; }\n.admin-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }\n.admin-card { background: #FFFFFF; border: var(--line); border-radius: var(--r-md); box-shadow: 5px 6px 0 rgba(30,27,24,0.25); padding: 30px 28px; }\n.admin-card-full { margin-top: 24px; }\n.admin-card h2 { font-weight: 700; font-size: 1.25rem; margin-bottom: 6px; color: var(--ink); }\n.admin-hint { font-size: 0.88rem; opacity: 0.7; margin-bottom: 18px; }\n.admin-form { display: flex; flex-direction: column; }\n.admin-form label { font-weight: 600; font-size: 0.78rem; text-transform: uppercase; letter-spacing: 0.06em; margin: 12px 0 5px; color: var(--blue-dark); }\n.admin-form input { font-family: var(--sans); font-size: 0.98rem; padding: 11px 13px; border: 2px solid var(--ink); border-radius: 8px; background: var(--cream); }\n.admin-form input:focus { outline: none; box-shadow: 3px 3px 0 var(--blue); }\n.admin-check { flex-direction: row; align-items: center; gap: 8px; margin-top: 16px; font-size: 0.9rem; color: var(--ink); text-transform: none; letter-spacing: 0; }\n.admin-check input { width: auto; }\n.admin-form .btn { margin-top: 20px; text-align: center; margin-right: 0; }\n.admin-list { list-style: none; display: flex; flex-direction: column; gap: 10px; }\n.admin-list li { display: flex; justify-content: space-between; align-items: center; gap: 12px; background: var(--blue-mist); border: 2px solid var(--ink); border-radius: 8px; padding: 12px 16px; }\n.admin-list strong { margin-right: 8px; color: var(--ink); }\n.admin-list span { font-size: 0.9rem; }\n.tag { font-size: 0.66rem; font-weight: 600; text-transform: uppercase; padding: 2px 8px; border-radius: 4px; margin-right: 6px; }\n.tag-blocked { background: var(--ink); color: var(--cream); }\n.admin-del { border: 2px solid var(--ink); background: #FFFFFF; color: #B23A2E; font-size: 1.2rem; font-weight: 700; width: 34px; height: 34px; border-radius: 8px; cursor: pointer; }\n.admin-del:hover { background: #FBE9E7; }\n.admin-empty { opacity: 0.6; font-style: italic; }\n.admin-table { width: 100%; border-collapse: collapse; margin-top: 10px; font-size: 0.9rem; }\n.admin-table th { text-align: left; padding: 10px 12px; border-bottom: 2px solid var(--ink); font-size: 0.76rem; text-transform: uppercase; letter-spacing: 0.06em; }\n.admin-table td { padding: 10px 12px; border-bottom: 1px dashed rgba(30,27,24,0.25); vertical-align: top; }\n.admin-table a { color: var(--blue-dark); font-weight: 600; }\n\n/* ---------------- RESPONSIVE ---------------- */\n@media (max-width: 900px) {\n  .nav-links { gap: 16px; }\n  .nav-links a:not(.nav-cta) { display: none; }\n  .hero-inner { grid-template-columns: 1fr; text-align: center; gap: 30px; }\n  .hero-copy { order: 2; }\n  .hero-visual { order: 1; }\n  .hero-actions, .hero-badges { justify-content: center; }\n  .hero-sub { margin-left: auto; margin-right: auto; }\n  .sticker { width: clamp(220px, 55vw, 300px); }\n  .why-grid { grid-template-columns: 1fr; }\n  .menu-grid { grid-template-columns: 1fr 1fr; }\n  .about, .events-teaser, .visit { grid-template-columns: 1fr; gap: 40px; }\n  .about-photo img { height: 300px; }\n  .gallery-grid { grid-template-columns: 1fr; }\n  .gallery-item img { height: 280px; }\n  .admin-grid { grid-template-columns: 1fr; }\n  .cal td { height: 84px; padding: 5px; }\n  .cal-event { display: none; }\n  .cal-day.has-event .cal-num { border-bottom: 3px solid var(--blue-deep); }\n}\n@media (max-width: 640px) {\n  .menu-grid { grid-template-columns: 1fr; }\n  .request-form { grid-template-columns: 1fr; }\n  .request { padding: 32px 24px; }\n}\n@media (prefers-reduced-motion: reduce) {\n  html { scroll-behavior: auto; }\n}\n'
TEXT['static/js/main.js'] = '/* ================================================================\n   SWEET BEAN CANTEEN — v3\n   Hero: cup spin-drops from above as you scroll; when it lands,\n   steam rises and "SWEET BEAN CANTEEN" stamps onto the sleeve.\n   Everything is driven by scroll position, so scrolling back up\n   plays the whole thing in reverse automatically.\n   ================================================================ */\n(function () {\n  const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;\n\n  // Fade the scroll hint out as the user scrolls past the hero.\n  const hint = document.getElementById("scrollHint");\n  if (hint) {\n    const onScroll = () => {\n      const p = Math.min(window.scrollY / (window.innerHeight * 0.5), 1);\n      hint.style.opacity = String(1 - p);\n    };\n    window.addEventListener("scroll", onScroll, { passive: true });\n    onScroll();\n  }\n\n  // Section reveals on scroll.\n  const revealEls = document.querySelectorAll(".reveal");\n  if ("IntersectionObserver" in window && !reduced) {\n    const io = new IntersectionObserver(\n      (entries) => {\n        entries.forEach((e) => {\n          if (e.isIntersecting) {\n            e.target.classList.add("is-in");\n            io.unobserve(e.target);\n          }\n        });\n      },\n      { threshold: 0.15 }\n    );\n    revealEls.forEach((el) => io.observe(el));\n  } else {\n    revealEls.forEach((el) => el.classList.add("is-in"));\n  }\n})();\n'
TEXT['static/img/gallery/README.txt'] = "Save photos from the Sweet Bean Canteen Facebook page and drop them\nin this folder (.jpg / .png / .webp). They will automatically appear\nin the site's gallery, replacing the placeholder graphics.\n"
TEXT['requirements.txt'] = 'Flask==3.1.3\ngunicorn==23.0.0\npsycopg2-binary==2.9.10\n'
TEXT['Procfile'] = 'web: gunicorn app:app\n'
TEXT['.gitignore'] = '__pycache__/\n*.pyc\nsweetbean.db\n.env\nvenv/\n.venv/\n'
TEXT['DEPLOY.md'] = '# Sweet Bean Canteen — deploy notes\n\n## Run locally\n    pip install flask\n    python app.py\n    # http://127.0.0.1:5000\nLocal uses a SQLite file (sweetbean.db) automatically. No setup needed.\n\n## Owner dashboard\n    /admin  → password from ADMIN_PASSWORD (default "sweetbean" locally)\nAdd events, block dates, and read event requests there. Changes appear on\nthe public site instantly.\n\n## Deploy to Render\n1. Push this folder to GitHub.\n2. Render → New → Web Service → point at the repo.\n   - Build command:  pip install -r requirements.txt\n   - Start command:  gunicorn app:app\n3. Render → New → Postgres (free). Copy its Internal Database URL.\n4. In the web service\'s Environment, add:\n   - DATABASE_URL      = (the Postgres URL from step 3)\n   - SECRET_KEY        = (any long random string)\n   - ADMIN_PASSWORD    = (owner\'s password)\n   - RESEND_API_KEY    = (from resend.com — free)   [optional but needed for email]\n   - OWNER_EMAIL       = (where event requests should go)\n   - FROM_EMAIL        = Sweet Bean Canteen <onboarding@resend.dev>\n5. Deploy. Tables auto-create on first boot.\n\nWithout DATABASE_URL it runs on SQLite (fine for a demo, but Render\'s free\ndisk resets — use Postgres for the real site).\n\nWithout RESEND_API_KEY, event requests still save to the dashboard; they just\nwon\'t email. The console prints them so nothing is lost.\n'
BIN['static/img/photos/iced-mocha.jpg'] = ''
BIN['static/img/photos/sherbet-float.jpg'] = ''
BIN['static/img/photos/croissant-sandwich.jpg'] = ''
BIN['static/img/photos/patio.jpg'] = ''

def main():
    print("Building Sweet Bean Canteen v7 (The Sticker) in:", ROOT, "\n")
    for rel, content in TEXT.items():
        dest = ROOT / rel
        dest.parent.mkdir(parents=True, exist_ok=True)
        dest.write_text(content, encoding="utf-8")
        print(f"  wrote  {rel}")
    for rel, b64 in BIN.items():
        dest = ROOT / rel
        dest.parent.mkdir(parents=True, exist_ok=True)
        dest.write_bytes(base64.b64decode(b64))
        print(f"  wrote  {rel}  (photo)")
    print("\nDone.  python app.py  ->  http://127.0.0.1:5000")
    print("Owner dashboard: /admin  (password: sweetbean)")

if __name__ == "__main__":
    main()